    if ((m=source.match(/^(研究方向|校验值|部分来源未完成)[：:](.*)$/))) return ({'研究方向':ja?'研究テーマ':'Research direction','校验值':ja?'チェックサム':'Checksum','部分来源未完成':ja?'未完了の情報源':'Incomplete sources'}[m[1]])+': '+m[2];
