    if ((m=source.match(/^(.+) 实时目录：(.+)$/))) return `${translated(m[1],language)} ${ja?'現在の一覧：':'Current catalog: '}${m[2]}`;
    if ((m=source.match(/^改用 (.+)$/))) return ja?`${m[1]} を使用`:`Use ${m[1]}`;
