    if ((m=source.match(/^API 验证未通过：(.+)$/))) return `${ja?'API 検証失敗：':'API verification failed: '}${translated(m[1],language)}`;
    if ((m=source.match(/^Memorive (.+)$/))) return 'Memorive '+translated(m[1],language);
    // A count or a page number with its word: English says 1 exchange, 2 exchanges, Page 4.
    if ((m=source.match(/^(\d+) (轮对话|页)$/))) return ja?`${m[1]} ${translated(m[2],language)}`:`${m[1]} ${m[2]==='页'?'page':'exchange'}${m[1]==='1'?'':'s'}`;
    if ((m=source.match(/^页 (\d+)$/))) return ja?`${translated('页',language)} ${m[1]}`:`Page ${m[1]}`;
    if ((m=source.match(/^CLI 返回的模型与当前模型标识不一致。(?:CLI 报告的模型：(.+))?$/))) return (ja?'CLI が返したモデルが現在のモデル ID と一致しません。':'The model the CLI returned differs from this model ID.')+(m[1]?(ja?'CLI が報告したモデル：':' Models the CLI reported: ')+m[1]:'');
    if ((m=source.match(/^当前任务 (\d+) 项$/))) return ja?`現在のタスク ${m[1]} 件`:`Current tasks: ${m[1]}`;
    if ((m=source.match(/^当前显示 (\d+) 条消息$/))) return ja?`${m[1]} 件のメッセージを表示`:`Showing ${m[1]} messages`;
    if ((m=source.match(/^显示 (\d+) 项，共 (\d+) 项$/))) return ja?`${m[2]} 件中 ${m[1]} 件を表示`:`Showing ${m[1]} of ${m[2]}`;
    if ((m=source.match(/^等待批准 (\d+) · 等待执行 (\d+) · 正在执行 (\d+) · 执行异常 (\d+) · 已经结束 (\d+)$/))) return ja?`承認待ち ${m[1]} · 実行待ち ${m[2]} · 実行中 ${m[3]} · エラー ${m[4]} · 終了 ${m[5]}`:`Approval ${m[1]} · Queued ${m[2]} · Running ${m[3]} · Failed ${m[4]} · Finished ${m[5]}`;
    if ((m=source.match(/^当前 (USD|RMB|JPY)，(点击)?切换为 (USD|RMB|JPY)( · 等待有效汇率)?$/))) return ja?`現在 ${m[1]}、${m[3]} に切り替え${m[4]?' · 有効な為替を待機中':''}`:`Current ${m[1]}; switch to ${m[3]}${m[4]?' · Awaiting valid exchange rates':''}`;
    if ((m=source.match(/^(.+)，作用：(.+)，(就绪|待设置)，模型或执行方式：(.+)$/))) return `${translated(m[1],language)}; ${translated(m[2],language)}; ${translated(m[3],language)}; ${translated(m[4],language)}`;
    if ((m=source.match(/^(\d+) 个可配置流程节点中 (\d+) 个已完成，无绕过节点；整理分析材料 单源继承 02，卡片准入与人工判断不计入配置分母$/))) return ja?`設定可能な ${m[1]} ノード中 ${m[2]} 完了。迂回なし。分析資料の整理は02を継承し、カード受入と人による判断は対象外です。`:`${m[2]} of ${m[1]} configurable nodes ready; no bypass. Analysis preparation inherits step 02; card admission and human judgment are excluded.`;
